SET threads TO 1;
ATTACH 'test.db' (ROW_GROUP_SIZE 8192);
USE test;
CREATE TABLE chicago_taxi (
"Trip ID"                    VARCHAR,
"Taxi ID"                    VARCHAR,
"Trip Start Timestamp"       TIMESTAMP,
"Trip End Timestamp"         TIMESTAMP,
"Trip Seconds"               VARCHAR,
"Trip Miles"                 DOUBLE,
"Pickup Census Tract"        BIGINT,
"Dropoff Census Tract"       BIGINT,
"Pickup Community Area"      BIGINT,
"Dropoff Community Area"     BIGINT,
"Fare"                       VARCHAR,
"Tips"                       VARCHAR,
"Tolls"                      VARCHAR,
"Extras"                     VARCHAR,
"Trip Total"                 VARCHAR,
"Payment Type"               VARCHAR,
"Company"                    VARCHAR,
"Pickup Centroid Latitude"   DOUBLE,
"Pickup Centroid Longitude"  DOUBLE,
"Pickup Centroid Location"   VARCHAR,
"Dropoff Centroid Latitude"  DOUBLE,
"Dropoff Centroid Longitude" DOUBLE,
"Dropoff Centroid  Location" VARCHAR
);
COPY chicago_taxi FROM 'chicago_taxi/chicago_taxi.csv' (FORMAT 'csv', delimiter ',', header 1, thousands ',');
